/** What `WINDOW_ZLIB` holds: 151,000 bytes. */
export const windowDataOf = (): Uint8Array => {
  const block = lcgBytesOf(1, 30_000)
  const data = new Uint8Array(5 * 30_000 + 1000)
  for (let i = 0; i < 5; i += 1) data.set(block, i * 30_000)
  data.set(lcgBytesOf(2, 1000), 5 * 30_000)

  return data
}

const WORDS = 'the quick brown fox jumps over the lazy dog image strip thumbnail'.split(' ')

/** What `TEXT_DYNAMIC_ZLIB` and `TEXT_FIXED_ZLIB` hold: 120,000 bytes of words picked by the seeded generator. */
export const textOf = (): Uint8Array => {
  let text = ''
  let state = 5
  while (text.length < 120_000) {
    state = (Math.imul(state, 1103515245) + 12345) >>> 0
    text += `${WORDS[(state >>> 16) % WORDS.length]} `
  }

  return new TextEncoder().encode(text.slice(0, 120_000))
}

